#!/usr/bin/env bash
# picture-it round 1, stage A: base plates (generate) + likeness scenes (edit). Parallel.
cd "$(dirname "$0")"
PI=./bin/picture-it
ID=$CONTENT_ROOT/assets/creator-cutouts/identity
run(){ id=$1; shift; ( s=$(date +%s); $PI "$@" -o gen/$id.png > logs/$id.out 2> logs/$id.err; echo "$id exit=$? $(( $(date +%s)-s ))s" | tee -a logs/times.log ) & }

run g1-desk generate --model flux-dev --size 1280x720 --prompt "A dark moody wooden desk at night, photographed straight on. A modern open laptop sits centered, its screen showing a dark minimal app dashboard with a left sidebar and, in the middle, a large white line-art ram head logo above the word 'Herdr.' in a monospace font. Warm orange bokeh lights in the dark background, subtle green accent glow. Leave the left and right thirds of the frame dark and uncluttered. Cinematic, high contrast, no people."
run g2-studio generate --model flux-dev --size 1280x720 --prompt "A dark modern podcast studio at night, no people. A black boom-arm microphone enters from the lower left. On the right, a floating dark glass UI panel of a web app with a left nav column and a large input box reading 'Build what's next.' Magenta and violet neon rim lighting, deep navy and black tones, shallow depth of field. Empty space in the left half for a person."
run g4-bg generate --model flux-schnell --size 1280x720 --prompt "A flat dark charcoal grey background with a subtle radial lighter centre and faint thin orange topographic contour lines in the top right corner only. Minimal graphic design backdrop, no text, no objects."
run g5-office generate --model flux-dev --size 1280x720 --prompt "A wide blue-toned modern open-plan tech office at night seen through glass, silhouettes of a few people working at desks with glowing monitors, soft bokeh, deep navy and electric blue palette, dark vignette on the right side. Cinematic, no text."
run g8-bg generate --model flux-schnell --size 1280x720 --prompt "A plain smooth muted steel blue studio wall background, soft even lighting, very subtle gradient, no objects, no text."

run g3-kenny edit --model banana-pro -i ref/ref3.jpg -i $ID/IMG_1535.jpg -i src/sourced/m5-hero.jpg -i gen/logo-claude.png -i gen/logo-openai.png -i gen/logo-deepseek.png --prompt "Create a 16:9 YouTube thumbnail photo. Figure 1 supplies ONLY the layout, framing and lighting mood; never copy its person, face or beard. Figure 2 is the man to show: keep his face exactly, do not widen, round, age, average, or blend it. He is on the left half, head and chest, looking straight at the camera with wide surprised eyes and raised eyebrows, holding a small square silver aluminium desktop computer box on his open palm at chest height on the right. Brilliant neon blue, violet, cyan and pink light beams explode upward out of the top of the box, with three floating glowing rounded-square app tiles above it tilted at different angles, showing the logos in Figure 4, Figure 5 and Figure 6 in white. In the top-left corner, a small square dark glass badge showing the chip from Figure 3 with the Apple logo and the text 'M5 ULTRA'. Dark studio room with RGB lights behind him, dramatic cool lighting."
run g6-kenny edit --model banana-pro -i ref/ref6.jpg -i src/anchor-1505-face.png -i src/sourced/iphone-colors.jpg --prompt "Create a 16:9 YouTube thumbnail photo. Copy the pose, framing and camera angle of Figure 1 only, never its person's face, glasses, or hair. The man is the man in Figure 2: keep his face exactly, including his age; do not widen, round, age, average, or blend it. He sits behind a large plain white table on the right half of the frame, his left forearm resting on the tabletop, and with his right arm he holds the light blue iPhone from Figure 3 very close to the camera on the left side, so the phone appears huge in the foreground, tilted slightly, showing its back and large camera plateau. Figure 3 supplies only the phone's exact design and colour. He wears a plain black t-shirt and no glasses. Behind him, a dark navy wall with thick glowing light-blue maze-like circuit lines. At the top, the title 'iPhone 18 Pro' in huge bold glossy light-blue gradient sans-serif letters, with the man's head slightly overlapping the bottom of the letters."
run g7-kenny edit --model banana-pro -i src/anchor-1505-face.png --prompt "Create a 16:9 extreme close-up portrait of the man in Figure 1, face filling the frame from forehead to chin, looking straight into the camera with a sad, intense stare and one single tear rolling down his cheek. Keep the face in Figure 1 exactly, including his age and smooth skin; do not widen, round, age, average, or blend it, and do not add wrinkles or lines. Around the edges of the frame, several small glass medicine vials with dark red crimped caps and white labels printed 'PEPTIDES' float at different angles, the nearest ones strongly out of focus in the foreground. Dramatic low-key lighting, dark red and black background edges, cinematic."
wait
